import{_ as a,o as r,c as o,ag as t}from"./chunks/framework.em2JOrjF.js";const p=JSON.parse('{"title":"Glossary","description":"","frontmatter":{},"headers":[],"relativePath":"guide/glossary.md","filePath":"guide/glossary.md"}'),n={name:"guide/glossary.md"};function i(l,e,h,s,d,u){return r(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="glossary" tabindex="-1">Glossary <a class="header-anchor" href="#glossary" aria-label="Permalink to &quot;Glossary&quot;">​</a></h1><p>Terms you&#39;ll encounter when using VERA, explained for day-to-day use.</p><hr><h2 id="b" tabindex="-1">B <a class="header-anchor" href="#b" aria-label="Permalink to &quot;B&quot;">​</a></h2><h3 id="billable-non-billable" tabindex="-1">Billable / non-billable <a class="header-anchor" href="#billable-non-billable" aria-label="Permalink to &quot;Billable / non-billable&quot;">​</a></h3><p>Whether the time you&#39;re logging generates revenue for the business. Most client work is billable. Internal projects (training, admin, R&amp;D) are not. VERA knows which is which — you don&#39;t need to set this yourself.</p><h3 id="briefing" tabindex="-1">Briefing <a class="header-anchor" href="#briefing" aria-label="Permalink to &quot;Briefing&quot;">​</a></h3><p>The message VERA sends each weekday morning. It summarises your recent hours, your work plan for the week, and (for managers and owners) the health of your portfolio. See <a href="./morning-briefing.html">The morning briefing</a>.</p><h3 id="burn-rate" tabindex="-1">Burn rate <a class="header-anchor" href="#burn-rate" aria-label="Permalink to &quot;Burn rate&quot;">​</a></h3><p>How quickly a project&#39;s hours are being used relative to what was planned. A project burning hours faster than expected will run out of budget before the deadline. Managers and owners see burn rate in their morning briefing and in retainer summaries.</p><hr><h2 id="e" tabindex="-1">E <a class="header-anchor" href="#e" aria-label="Permalink to &quot;E&quot;">​</a></h2><h3 id="envelope" tabindex="-1">Envelope <a class="header-anchor" href="#envelope" aria-label="Permalink to &quot;Envelope&quot;">​</a></h3><p>A work plan your manager has assigned to you on a specific project and task type. It defines how many hours you&#39;re expected to contribute. Your envelope shows up in your morning briefing as Plan / Logged / Remaining.</p><p>Envelopes are planning tools — they don&#39;t restrict you from logging time. You can log to any active project whether or not you have an envelope for it.</p><hr><h2 id="l" tabindex="-1">L <a class="header-anchor" href="#l" aria-label="Permalink to &quot;L&quot;">​</a></h2><h3 id="leave" tabindex="-1">Leave <a class="header-anchor" href="#leave" aria-label="Permalink to &quot;Leave&quot;">​</a></h3><p>An extended absence (parental, compassionate, unpaid, and so on). Requested through VERA and approved by a manager, the same way as <a href="./time-off.html">time off</a>.</p><h3 id="log-logging" tabindex="-1">Log / logging <a class="header-anchor" href="#log-logging" aria-label="Permalink to &quot;Log / logging&quot;">​</a></h3><p>The act of recording your hours in VERA. &quot;Log 3 hours on Nike, design&quot; is all it takes. See <a href="./logging-time.html">Logging time</a>.</p><hr><h2 id="m" tabindex="-1">M <a class="header-anchor" href="#m" aria-label="Permalink to &quot;M&quot;">​</a></h2><h3 id="morning-briefing" tabindex="-1">Morning briefing <a class="header-anchor" href="#morning-briefing" aria-label="Permalink to &quot;Morning briefing&quot;">​</a></h3><p>See <a href="#briefing">Briefing</a>.</p><hr><h2 id="p" tabindex="-1">P <a class="header-anchor" href="#p" aria-label="Permalink to &quot;P&quot;">​</a></h2><h3 id="period" tabindex="-1">Period <a class="header-anchor" href="#period" aria-label="Permalink to &quot;Period&quot;">​</a></h3><p>A single billing cycle within a retainer — typically one month. Each period has its own hours budget and contract value. When a period closes, a new one opens. You log time against the current period, not the retainer as a whole.</p><h3 id="project" tabindex="-1">Project <a class="header-anchor" href="#project" aria-label="Permalink to &quot;Project&quot;">​</a></h3><p>The thing you&#39;re working on. Every hour you log goes to a project. Projects belong to clients (or to your own company, for internal work). Your manager or owner sets up projects — you just log to them.</p><h3 id="pto" tabindex="-1">PTO <a class="header-anchor" href="#pto" aria-label="Permalink to &quot;PTO&quot;">​</a></h3><p>Paid time off. Requested through VERA and approved by your manager before being recorded. You can&#39;t log PTO directly — it has to go through the approval process. See <a href="./time-off.html">Time off</a>.</p><hr><h2 id="r" tabindex="-1">R <a class="header-anchor" href="#r" aria-label="Permalink to &quot;R&quot;">​</a></h2><h3 id="retainer" tabindex="-1">Retainer <a class="header-anchor" href="#retainer" aria-label="Permalink to &quot;Retainer&quot;">​</a></h3><p>An ongoing client engagement with a fixed fee per period (usually monthly). The client pays a set amount; the team delivers a set number of hours. VERA tracks how much of the current period has been used. See <a href="./projects.html">Projects and tasks</a> for more on retainers.</p><hr><h2 id="s" tabindex="-1">S <a class="header-anchor" href="#s" aria-label="Permalink to &quot;S&quot;">​</a></h2><h3 id="sick-day" tabindex="-1">Sick day <a class="header-anchor" href="#sick-day" aria-label="Permalink to &quot;Sick day&quot;">​</a></h3><p>A day off due to illness. Unlike PTO, sick days don&#39;t require a formal request — your manager logs them on your behalf. See <a href="./time-off.html">Time off</a>.</p><h3 id="sprint" tabindex="-1">Sprint <a class="header-anchor" href="#sprint" aria-label="Permalink to &quot;Sprint&quot;">​</a></h3><p>A time-boxed delivery unit in an Agile project. Like a retainer period, each sprint has its own hours and contract value. When one sprint closes, the next one opens.</p><hr><h2 id="t" tabindex="-1">T <a class="header-anchor" href="#t" aria-label="Permalink to &quot;T&quot;">​</a></h2><h3 id="task" tabindex="-1">Task <a class="header-anchor" href="#task" aria-label="Permalink to &quot;Task&quot;">​</a></h3><p>The type of work you&#39;re doing within a project — Design, Development, Strategy, Admin, and so on. Each project has a specific set of tasks enabled for it. If you have a single task planned on a project, VERA applies it automatically when you log time. If you have multiple, they&#39;ll ask. To see which tasks are available: &quot;What tasks are on the Nike project?&quot;</p><h3 id="team-member" tabindex="-1">Team member <a class="header-anchor" href="#team-member" aria-label="Permalink to &quot;Team member&quot;">​</a></h3><p>The default role in VERA. Team members log their own time and see their own data. See <a href="./roles.html">Your role in VERA</a>.</p><h3 id="time-entry" tabindex="-1">Time entry <a class="header-anchor" href="#time-entry" aria-label="Permalink to &quot;Time entry&quot;">​</a></h3><p>A single record of work: a date, a project, a number of hours, and usually a task. Created when you log time. Can be edited or deleted if something&#39;s wrong.</p><hr><h2 id="w" tabindex="-1">W <a class="header-anchor" href="#w" aria-label="Permalink to &quot;W&quot;">​</a></h2><h3 id="work-plan" tabindex="-1">Work plan <a class="header-anchor" href="#work-plan" aria-label="Permalink to &quot;Work plan&quot;">​</a></h3><p>See <a href="#envelope">Envelope</a>.</p>',55)])])}const m=a(n,[["render",i]]);export{p as __pageData,m as default};
